using Clock=std::chrono::steady_clock;
static void check(cudaError_t e){if(e!=cudaSuccess)throw std::runtime_error(cudaGetErrorString(e));}
__declspec(noinline) static void crt(void*d,const void*s,size_t n){std::memcpy(d,s,n);}
__declspec(noinline) static void copy256(void*d,const void*s,size_t n,bool nt){
    auto*dst=(uint8_t*)d;auto*src=(const uint8_t*)s;
    size_t head=std::min(n,(64-((uintptr_t)dst&63))&63);
    std::memcpy(dst,src,head);dst+=head;src+=head;n-=head;
    while(n>=128){
        auto a=_mm256_loadu_si256((const __m256i*)(src));auto b=_mm256_loadu_si256((const __m256i*)(src+32));
        auto c=_mm256_loadu_si256((const __m256i*)(src+64));auto e=_mm256_loadu_si256((const __m256i*)(src+96));
        if(nt){_mm256_stream_si256((__m256i*)dst,a);_mm256_stream_si256((__m256i*)(dst+32),b);
            _mm256_stream_si256((__m256i*)(dst+64),c);_mm256_stream_si256((__m256i*)(dst+96),e);}
        else{_mm256_storeu_si256((__m256i*)dst,a);_mm256_storeu_si256((__m256i*)(dst+32),b);
            _mm256_storeu_si256((__m256i*)(dst+64),c);_mm256_storeu_si256((__m256i*)(dst+96),e);}
        dst+=128;src+=128;n-=128;
    }
    std::memcpy(dst,src,n);if(nt)_mm_sfence();_mm256_zeroupper();
}
__declspec(noinline) static void nt256(void*d,const void*s,size_t n){copy256(d,s,n,true);}
__declspec(noinline) static void cached256(void*d,const void*s,size_t n){copy256(d,s,n,false);}
int main(){try{
    int cpu[4];__cpuid(cpu,1);if(!(cpu[2]&(1<<27)) || !(cpu[2]&(1<<28)) || (_xgetbv(0)&6)!=6)return 2;
    __cpuidex(cpu,7,0);if(!(cpu[1]&(1<<5)))return 2;
    const size_t bytes=4096*1280/256*144+512, source_bytes=512ull<<20;
    std::vector<uint8_t> source(source_bytes);for(size_t i=0;i<source.size();++i)source[i]=uint8_t(i*131+i/4093);
