    using Copy=void(*)(void*,const void*,size_t);
    Copy methods[]={crt,cached256,nt256};const char*names[]={"crt","avx2-cached","avx2-nt"};
    for(int round=-1;round<6;++round)for(int v=0;v<3;++v){int mode=round%2==0?2-v:v;auto start=Clock::now();
